select case when credit_limit >= 16700 then 'high' when credit_limit >= 4400 then 'mid' else 'low' end as credit_limit_bucket, segment, date_trunc('MONTH', signup_date) as signup_month, round((100 * sum(case when segment = 'SMB' then 1 else 0 end)) / count(*), 1) as pct_smb from customers where (credit_limit > 15900 and segment is not null) or age is not null group by credit_limit_bucket, segment, signup_month order by signup_month asc
